import sys
input = sys.stdin.read().split()
index = 0

def can_be_k_balanced(n, k, s):
    if k == 2:
        count_0 = s.count('0')
        count_1 = s.count('1')
        count_q = s.count('?')
        return (count_0 + count_q // 2 == count_1 + (count_q - count_q // 2))

    prefix_sum = [0] * (n + 1)
    for i in range(n):
        prefix_sum[i + 1] = prefix_sum[i] + (1 if s[i] == '1' else -1) if s[i] != '?' else prefix_sum[i]

    balance = [0] * k
    question_marks = [0] * k

    for i in range(k):
        if s[i] == '?':
            question_marks[i % k] += 1
        else:
            balance[i % k] += (1 if s[i] == '1' else -1)

    if any(abs(balance[i]) > question_marks[i] for i in range(k)):
        return False

    for i in range(k, n):
        if s[i] == '?':
            question_marks[i % k} += 1
        else:
            balance[i % k] += (0 if s[i] == '1' else -2)

        if abs(balance[i % k]) > question_marks[i % k]:
            return False

    return True

t = int(input[index])
index += 1
results = []
for _ in range(t):
    n = int(input[index])
    k = int(input[index + 1])
    s = input[index + 2]
    index += 3
    results.append("YES" if can_be_k_balanced(n, k, s) else "NO")

print("\n".join(results))
